//! Model catalog: context windows, output limits, feature flags and prices.
//!
//! Sources, lowest to highest priority:
//! 1. `assets/models.json`, a bundled offline snapshot;
//! 2. a user cache refreshed from <https://models.dev> in the background
//!    (or with `okeanos models update`).
//!
//! Neither is hand-edited: both are generated by [`from_models_dev`]. Explicit
//! `[model.capabilities]` config always wins over the catalog, and models absent
//! from every source fall back to the name heuristics in the classifier.

use crate::context::tokens::ModelPricing;
use crate::model::ModelTier;
use serde::{Deserialize, Serialize};
use serde_json::Value;
use std::collections::{HashMap, HashSet};
use std::path::{Path, PathBuf};
use std::sync::OnceLock;
use std::time::{Duration, SystemTime};
use thiserror::Error;

pub const MODELS_DEV_URL: &str = "https://models.dev/api.json";

/// How old the cache may get before a background refresh is attempted.
pub const CACHE_MAX_AGE: Duration = Duration::from_secs(24 * 60 * 60);

/// Providers whose own listings are authoritative for their models, in
/// priority order. Resellers are skipped: they duplicate ids with different prices.
const FIRST_PARTY: &[&str] = &[
    "anthropic",
    "openai",
    "google",
    "xai",
    "deepseek",
    "mistral",
    "moonshotai",
    "zai",
    "alibaba",
    "minimax",
    "cohere",
];

#[derive(Debug, Error)]
pub enum CatalogError {
    #[error("HTTP request failed: {0}")]
    Http(#[from] reqwest::Error),
    #[error("invalid JSON: {0}")]
    Json(#[from] serde_json::Error),
    #[error("I/O error: {0}")]
    Io(#[from] std::io::Error),
    #[error("models.dev returned no usable models")]
    Empty,
}

/// One catalog row, matched by normalized id prefix.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CatalogEntry {
    pub id: String,
    pub context: usize,
    pub max_output: usize,
    pub tool_calling: bool,
    #[serde(default)]
    pub vision: bool,
    #[serde(default)]
    pub reasoning: bool,
    #[serde(default)]
    pub input_per_million: f64,
    #[serde(default)]
    pub output_per_million: f64,
}

impl CatalogEntry {
    /// `None` when the source listed no prices.
    pub fn pricing(&self) -> Option<ModelPricing> {
        (self.input_per_million > 0.0 || self.output_per_million > 0.0).then_some(ModelPricing {
            input_per_million: self.input_per_million,
            output_per_million: self.output_per_million,
        })
    }

    /// Tier derived from capabilities rather than names: Small cannot call
    /// tools, has a tiny window, or is priced under $1/M output; Frontier is a
    /// large-window tool caller priced at $2+/M output (price is the only
    /// portable quality signal; unpriced models stay Mid); the rest is Mid.
    pub fn tier(&self) -> ModelTier {
        let cheap = self.output_per_million > 0.0 && self.output_per_million < 1.0;
        if !self.tool_calling || self.context < 32_000 || cheap {
            ModelTier::Small
        } else if self.context >= 128_000 && self.output_per_million >= 2.0 {
            ModelTier::Frontier
        } else {
            ModelTier::Mid
        }
    }
}

/// Lowercase, drop any `vendor/` prefix and `:tag` suffix, and treat `.` as `-`.
fn normalize(name: &str) -> String {
    let base = name.rsplit('/').next().unwrap_or(name);
    let base = base.split(':').next().unwrap_or(base);
    base.to_lowercase().replace('.', "-")
}

/// Convert a models.dev `api.json` document into catalog entries.
pub fn from_models_dev(root: &Value) -> Vec<CatalogEntry> {
    let mut seen = HashSet::new();
    let mut out = Vec::new();
    for provider in FIRST_PARTY {
        let Some(models) = root
            .get(*provider)
            .and_then(|p| p.get("models"))
            .and_then(Value::as_object)
        else {
            continue;
        };
        for (key, m) in models {
            let context = m
                .pointer("/limit/context")
                .and_then(Value::as_u64)
                .unwrap_or(0) as usize;
            let text_out = m
                .pointer("/modalities/output")
                .and_then(Value::as_array)
                .is_none_or(|o| o.iter().any(|v| v.as_str() == Some("text")));
            let id = normalize(m.get("id").and_then(Value::as_str).unwrap_or(key));
            if context == 0 || !text_out || !seen.insert(id.clone()) {
                continue;
            }
            let max_output = m
                .pointer("/limit/output")
                .and_then(Value::as_u64)
                .filter(|&n| n > 0)
                .map_or(context.min(8192), |n| n as usize);
            let flag = |k: &str| m.get(k).and_then(Value::as_bool).unwrap_or(false);
            let price = |k: &str| m.pointer(k).and_then(Value::as_f64).unwrap_or(0.0);
            out.push(CatalogEntry {
                id,
                context,
                max_output,
                tool_calling: flag("tool_call"),
                vision: m
                    .pointer("/modalities/input")
                    .and_then(Value::as_array)
                    .is_some_and(|i| i.iter().any(|v| v.as_str() == Some("image"))),
                reasoning: flag("reasoning"),
                input_per_million: price("/cost/input"),
                output_per_million: price("/cost/output"),
            });
        }
    }
    out.sort_by(|a, b| a.id.cmp(&b.id));
    out
}

/// Download and convert the current models.dev listing.
pub async fn fetch() -> Result<Vec<CatalogEntry>, CatalogError> {
    let body: Value = reqwest::Client::builder()
        .timeout(Duration::from_secs(30))
        .build()?
        .get(MODELS_DEV_URL)
        .send()
        .await?
        .error_for_status()?
        .json()
        .await?;
    let entries = from_models_dev(&body);
    if entries.is_empty() {
        return Err(CatalogError::Empty);
    }
    Ok(entries)
}

/// Write entries atomically (temp file + rename).
pub fn write_entries(path: &Path, entries: &[CatalogEntry]) -> Result<(), CatalogError> {
    if let Some(dir) = path.parent() {
        std::fs::create_dir_all(dir)?;
    }
    let tmp = path.with_extension("json.tmp");
    std::fs::write(&tmp, serde_json::to_vec(entries)?)?;
    std::fs::rename(&tmp, path)?;
    Ok(())
}

pub fn read_entries(path: &Path) -> Option<Vec<CatalogEntry>> {
    serde_json::from_slice(&std::fs::read(path).ok()?).ok()
}

/// Missing or older than `max_age`.
pub fn is_stale(path: &Path, max_age: Duration) -> bool {
    std::fs::metadata(path)
        .and_then(|m| m.modified())
        .ok()
        .and_then(|t| SystemTime::now().duration_since(t).ok())
        .is_none_or(|age| age > max_age)
}

pub fn cache_path() -> Option<PathBuf> {
    dirs::cache_dir().map(|d| d.join("okeanos").join("catalog.json"))
}

/// Refresh the cache in the background when it is stale. Best effort: failures
/// are logged at debug level and never surface to the user. The refreshed data
/// is picked up on the next start.
pub fn spawn_background_refresh() {
    let Some(path) = cache_path() else { return };
    if !is_stale(&path, CACHE_MAX_AGE) {
        return;
    }
    tokio::spawn(async move {
        match fetch().await {
            Ok(entries) => {
                if let Err(e) = write_entries(&path, &entries) {
                    tracing::debug!("catalog cache write failed: {e}");
                }
            }
            Err(e) => tracing::debug!("catalog refresh failed: {e}"),
        }
    });
}

static CATALOG: OnceLock<Vec<CatalogEntry>> = OnceLock::new();

/// Bundled snapshot overlaid with the user cache (cache wins per id).
fn entries() -> &'static [CatalogEntry] {
    CATALOG.get_or_init(|| {
        let bundled: Vec<CatalogEntry> =
            serde_json::from_str(include_str!("../../assets/models.json"))
                .expect("assets/models.json is valid");
        let cached = cache_path()
            .and_then(|p| read_entries(&p))
            .unwrap_or_default();
        merge(bundled, cached)
    })
}

fn merge(base: Vec<CatalogEntry>, overlay: Vec<CatalogEntry>) -> Vec<CatalogEntry> {
    let mut map: HashMap<String, CatalogEntry> =
        base.into_iter().map(|e| (e.id.clone(), e)).collect();
    map.extend(overlay.into_iter().map(|e| (e.id.clone(), e)));
    let mut all: Vec<_> = map.into_values().collect();
    all.sort_by(|a, b| a.id.cmp(&b.id));
    all
}

/// Longest-prefix lookup in `entries`. The prefix must end at a `-`/`@`
/// boundary so that `gpt-4` can never match `gpt-4o`.
fn lookup_in<'a>(entries: &'a [CatalogEntry], model: &str) -> Option<&'a CatalogEntry> {
    let name = normalize(model);
    entries
        .iter()
        .filter(|e| {
            name.strip_prefix(e.id.as_str())
                .is_some_and(|rest| rest.is_empty() || rest.starts_with(['-', '@']))
        })
        .max_by_key(|e| e.id.len())
}

pub fn lookup(model: &str) -> Option<&'static CatalogEntry> {
    lookup_in(entries(), model)
}

/// List pricing for `model`, if it is in the catalog and priced.
pub fn pricing(model: &str) -> Option<ModelPricing> {
    lookup(model).and_then(CatalogEntry::pricing)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn entry(id: &str) -> CatalogEntry {
        CatalogEntry {
            id: id.into(),
            context: 200_000,
            max_output: 8192,
            tool_calling: true,
            vision: false,
            reasoning: false,
            input_per_million: 1.0,
            output_per_million: 5.0,
        }
    }

    #[test]
    fn longest_prefix_with_boundary_and_normalization() {
        let es = vec![
            entry("gpt-4o"),
            entry("gpt-4o-mini"),
            entry("claude-haiku-4-5"),
        ];
        assert_eq!(lookup_in(&es, "gpt-4o-mini").unwrap().id, "gpt-4o-mini");
        assert_eq!(lookup_in(&es, "gpt-4o-2024-08-06").unwrap().id, "gpt-4o");
        assert_eq!(
            lookup_in(&es, "anthropic/claude-haiku-4.5@20251001")
                .unwrap()
                .id,
            "claude-haiku-4-5"
        );
        assert_eq!(lookup_in(&es, "openai/gpt-4o:free").unwrap().id, "gpt-4o");
        assert!(lookup_in(&es, "gpt-4").is_none());
        assert!(lookup_in(&es, "gpt-4ox").is_none());
    }

    #[test]
    fn cache_overrides_bundled_per_id() {
        let mut newer = entry("a");
        newer.context = 1;
        let merged = merge(vec![entry("a"), entry("b")], vec![newer, entry("c")]);
        assert_eq!(merged.len(), 3);
        assert_eq!(lookup_in(&merged, "a").unwrap().context, 1);
    }

    #[test]
    fn converts_models_dev_first_party_only() {
        let doc: Value = serde_json::from_str(
            r#"{
              "anthropic": {"models": {
                "claude-x": {"id":"claude-x","tool_call":true,"reasoning":true,
                  "modalities":{"input":["text","image"],"output":["text"]},
                  "limit":{"context":1000000,"output":64000},
                  "cost":{"input":3,"output":15}},
                "embed": {"id":"embed","limit":{"context":8000},"modalities":{"output":["vector"]}}}},
              "reseller": {"models": {"claude-x": {"id":"claude-x","limit":{"context":5}}}},
              "openai": {"models": {"Gpt-5.1": {"limit":{"context":400000}}}}
            }"#,
        )
        .unwrap();
        let es = from_models_dev(&doc);
        assert_eq!(es.len(), 2);
        let c = lookup_in(&es, "claude-x").unwrap();
        assert!(c.vision && c.reasoning && c.tool_calling);
        assert_eq!((c.context, c.max_output), (1_000_000, 64_000));
        assert_eq!(c.tier(), ModelTier::Frontier);
        let g = lookup_in(&es, "gpt-5.1").unwrap();
        assert_eq!(g.max_output, 8192);
        assert!(g.pricing().is_none());
        assert_eq!(g.tier(), ModelTier::Small); // no tool_call flag
    }

    #[test]
    fn tier_follows_capabilities() {
        let mut e = entry("m");
        assert_eq!(e.tier(), ModelTier::Frontier);
        e.output_per_million = 1.5;
        assert_eq!(e.tier(), ModelTier::Mid);
        e.output_per_million = 0.6;
        assert_eq!(e.tier(), ModelTier::Small);
        e.output_per_million = 1.5;
        e.context = 16_000;
        assert_eq!(e.tier(), ModelTier::Small);
    }

    #[test]
    fn cache_roundtrip_and_staleness() {
        let dir = std::env::temp_dir().join(format!("okeanos-catalog-{}", std::process::id()));
        let path = dir.join("catalog.json");
        assert!(is_stale(&path, CACHE_MAX_AGE));
        write_entries(&path, &[entry("a")]).unwrap();
        assert_eq!(read_entries(&path).unwrap()[0].id, "a");
        assert!(!is_stale(&path, CACHE_MAX_AGE));
        assert!(is_stale(&path, Duration::ZERO));
        let _ = std::fs::remove_dir_all(dir);
    }

    #[test]
    fn bundled_snapshot_parses() {
        assert!(!entries().is_empty());
    }
}
